referenceSolutions.javascript:
export function solve(values) {
  return values.map((value) => {
    const isArray = Array.isArray(value);
    const isObject = value !== null && typeof value === "object";
    const isPlainObject = isObject && !isArray;
    const isEmptyContainer = isArray
      ? value.length === 0
      : isPlainObject && Object.keys(value).length === 0;
    return { isArray, isObject, isPlainObject, isEmptyContainer };
  });
}

